export class APIError extends Error {
  status: number;
  /**
   * The envelope's machine-readable code, when the server sent one. The message
   * is what a person reads; the code is what a screen branches on, so a refusal
   * can offer the way out instead of only naming the problem.
   */
  code: string;
  constructor(status: number, message: string, code = "") {
    super(message);
    this.name = "APIError";
    this.status = status;
    this.code = code;
  }
}

export async function api<T>(path: string, options?: RequestInit): Promise<T> {
  const response = await fetch(path, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...(options?.headers || {}),
    },
    credentials: "same-origin",
  });
  if (response.status === 204) return undefined as T;
  const body = await response.json().catch(() => ({}));
  if (!response.ok)
    throw new APIError(
      response.status,
      body?.error?.message || `요청 실패 (${response.status})`,
      body?.error?.code || "",
    );
  return body as T;
}

export const post = <T>(path: string, body: unknown) =>
  api<T>(path, { method: "POST", body: JSON.stringify(body) });
export const patch = <T>(path: string, body: unknown) =>
  api<T>(path, { method: "PATCH", body: JSON.stringify(body) });
export const put = <T>(path: string, body: unknown) =>
  api<T>(path, { method: "PUT", body: JSON.stringify(body) });
export const del = <T>(path: string) => api<T>(path, { method: "DELETE" });

export function can(user: Principal, permission: string) {
  if (
    permission === "*.read" &&
    user.permissions.some(
      (got) => got === "*" || got === "*.read" || got.endsWith(".read"),
    )
  )
    return true;
  return user.permissions.some(
    (got) =>
      got === "*" ||
      got === permission ||
      (got.endsWith(".*") && permission.startsWith(got.slice(0, -1))) ||
      (got.startsWith("*.") && permission.endsWith(got.slice(1))),
  );
}

/**
 * An amount in the currency the record it came from is priced in.
 *
 * Every amount used to be rendered as won whatever it was stored under, which
 * is not a formatting detail: the portal's quote form offered four currencies,
 * so a bid of 50,000 USD reached the buyer's comparison table as ₩50,000 and
 * sat at the top of it next to quotes of ₩68,000,000. Nothing in the
 * application converts between two currencies, so the only honest thing a
 * screen can do is say which one the number is in.
 *
 * The code is defaulted rather than required because the columns are
 * `NOT NULL DEFAULT 'KRW'`, and left to `Intl` for the number of decimals: won
 * and yen are quoted whole, dollars and euros to the cent. An unknown code
 * makes `Intl` throw, so the amount falls back to a bare number with the code
 * beside it rather than taking the page down.
 */
export function money(value?: number | null, currency?: string | null) {
  if (value == null || !Number.isFinite(value)) return "—";
  const code = (currency || "KRW").toUpperCase();
  try {
    return new Intl.NumberFormat("ko-KR", {
      style: "currency",
      currency: code,
    }).format(value);
  } catch {
    return `${new Intl.NumberFormat("ko-KR").format(value)} ${code}`;
  }
}

/**
 * Whether a failed session check means the service could not answer, rather
 * than that the caller is signed out.
 *
 * Only a refusal means the session is gone. A server error, or no answer at all
 * because the request never arrived — `fetch` rejects with a TypeError there,
 * not an APIError — means the question went unanswered, and showing the sign-in
 * form tells someone they were logged out when they were not.
 */
export function sessionUnavailable(reason: unknown) {
  return !(reason instanceof APIError && reason.status === 401);
}

const CALENDAR_DATE = /^\d{4}-\d{2}-\d{2}$/;

function parseTimestamp(value?: string | null) {
  if (!value) return undefined;
  // A bare YYYY-MM-DD is a calendar date, not an instant. `new Date` reads it as
  // UTC midnight, which renders as the previous day everywhere west of UTC — a
  // contract ending on the 24th showed as the 23rd. Build it in local time so
  // the day a person typed is the day they see.
  if (CALENDAR_DATE.test(value)) {
    const [year, month, day] = value.split("-").map(Number);
    const parsed = new Date(year, month - 1, day);
    // The Date constructor wraps overflow rather than refusing it:
    // new Date(2026, 12, 45) is the 14th of February 2027, and "2026-02-31"
    // becomes the 3rd of March. A stored value that is not a date would render
    // as a plausible wrong day, which is worse than rendering as nothing.
    // Checking the parts survived also rejects the 29th of a non-leap
    // February while keeping it in a leap one.
    if (
      parsed.getFullYear() !== year ||
      parsed.getMonth() !== month - 1 ||
      parsed.getDate() !== day
    ) {
      return undefined;
    }
    return parsed;
  }
  // PostgreSQL may serialize UTC offsets as `+00`; browsers require `+00:00`.
  const parsed = new Date(value.replace(/([+-]\d{2})$/, "$1:00"));
  return Number.isNaN(parsed.getTime()) ? undefined : parsed;
}

/**
 * A date as YYYY-MM-DD in the viewer's own calendar. `toISOString` answers in
 * UTC, so it names yesterday for the first nine hours of every Korean day.
 */
export function isoDate(d: Date) {
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

/** Today in the viewer's own calendar. */
export function todayISO() {
  return isoDate(new Date());
}

export function date(value?: string | null) {
  const parsed = parseTimestamp(value);
  if (!parsed) return "—";
  return new Intl.DateTimeFormat("ko-KR", {
    year: "numeric",
    month: "short",
    day: "numeric",
  }).format(parsed);
}

/**
 * Date, time and seconds, for logs where two rows can share a minute.
 *
 * Intl.DateTimeFormat throws RangeError on an unparseable value rather than
 * returning something harmless, so a single malformed timestamp would take the
 * whole panel down through the error boundary. Going through parseTimestamp
 * turns that into an em dash.
 */
export function logTime(value?: string | null) {
  const parsed = parseTimestamp(value);
  if (!parsed) return "—";
  return new Intl.DateTimeFormat("ko-KR", {
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  }).format(parsed);
}

/** Date plus time, for values where the hour distinguishes one row from another. */
export function dateTime(value?: string | null) {
  const parsed = parseTimestamp(value);
  if (!parsed) return "—";
  return new Intl.DateTimeFormat("ko-KR", {
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(parsed);
}

/** Short relative phrasing such as "3분 전"; falls back to an absolute date. */
export function timeAgo(value?: string | null) {
  const parsed = parseTimestamp(value);
  if (!parsed) return "—";
  const seconds = Math.round((Date.now() - parsed.getTime()) / 1000);
  if (seconds < 60) return "방금";
  const units: [Intl.RelativeTimeFormatUnit, number][] = [
    ["minute", 60],
    ["hour", 3600],
    ["day", 86400],
  ];
  const formatter = new Intl.RelativeTimeFormat("ko-KR", { numeric: "auto" });
  for (let i = units.length - 1; i >= 0; i--) {
    const [unit, size] = units[i];
    if (seconds >= size) return formatter.format(-Math.floor(seconds / size), unit);
  }
  return dateTime(value);
}

